109	/// Parses `{:else if expression} ...`
110	pub(crate) fn parse_else_if_clause(p: &mut HtmlParser) -> ParsedSyntax {
111	    if !p.at(T!["{:"]) {
112	        return Absent;
113	    }
114	    let m = p.start();
115	    let checkpoint = p.checkpoint();
116	
117	    p.bump_with_context(T!["{:"], HtmlLexContext::Svelte);
118	
119	    p.expect_with_context(T![else], HtmlLexContext::Svelte);
120	
121	    if p.at(T!['}']) {
122	        // It's an `{:else}` block, we rewind the parsing and exit early
123	        m.abandon(p);
124	        p.rewind(checkpoint);
125	        return Absent;
126	    }
127	    p.expect_with_context(T![if], HtmlLexContext::single_expression());
128	
129	    parse_single_text_expression_content(p).or_add_diagnostic(p, |p, range| {
130	        expected_expression(p, range.sub_start(m.start()))
131	    });
132	
133	    p.expect(T!['}']);
134	
135	    SvelteElementList::new()
136	        .with_stop_at_curly_colon()
137	        .parse_list(p);
138	
